import { useEffect, useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { ArrowUp, Info, MessageCircleMore, ShieldCheck } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { AppPageHero } from "@/components/app/AppPageHero";
import { portalRepository } from "@/services/supabase/portal";
import { usePageMeta } from "@/hooks/usePageMeta";

export default function MessagesPage() {
  usePageMeta("Messages", "Échangez avec l’équipe et conservez le contexte du dossier.");
  const client = useQueryClient();
  const { data, isLoading, error } = useQuery({ queryKey: ["portal", "snapshot"], queryFn: portalRepository.getSnapshot, refetchInterval: 15_000 });
  const [body, setBody] = useState("");
  const unreadIds = data?.messages.filter((message) => !message.isOwn && !message.read).map((message) => message.id) ?? [];
  useEffect(() => {
    const ids = data?.messages.filter((message) => !message.isOwn && !message.read).map((message) => message.id) ?? [];
    if (ids.length) void portalRepository.markMessagesRead(ids).then(() => client.invalidateQueries({ queryKey: ["portal", "snapshot"] }));
  }, [client, data?.messages]);
  const mutation = useMutation({ mutationFn: () => data?.conversationId ? portalRepository.sendMessage(data.conversationId, body) : Promise.reject(new Error("Aucune conversation n’est encore associée au projet.")), onSuccess: async () => { setBody(""); await client.invalidateQueries({ queryKey: ["portal", "snapshot"] }); } });
  return <div className="mx-auto max-w-[1180px] space-y-5"><AppPageHero icon={MessageCircleMore} eyebrow="Messagerie du projet" title={<>Des échanges conservés <span className="gradient-text">dans leur contexte.</span></>} description="La conversation est rattachée au projet et filtrée par les permissions du compte connecté." stat={{ value: String(unreadIds.length), label: "Non lus" }} />{error ? <Card className="p-5 text-[color:var(--blue)]">{error instanceof Error ? error.message : "Chargement impossible"}</Card> : null}<Card className="overflow-hidden"><header className="flex items-center justify-between border-b border-[var(--line)] px-5 py-4"><div><p className="font-semibold">Équipe Orée</p><p className="mt-1 text-xs text-[color:var(--muted)]">{data?.project?.displayName ?? "Conversation du projet"}</p></div><span className="grid size-11 place-items-center rounded-full bg-[var(--mint)] text-xs font-bold">OR</span></header><div className="min-h-[520px] space-y-5 bg-[var(--paper)] p-5 sm:p-7">{isLoading ? <p className="text-center text-sm text-[color:var(--muted)]">Chargement des messages…</p> : null}{data?.messages.map((message) => <div key={message.id} className={`flex ${message.isOwn ? "justify-end" : "justify-start"}`}><div className={`max-w-[82%] rounded-[22px] px-4 py-3 text-sm leading-6 shadow-sm ${message.isOwn ? "rounded-tr-md bg-[var(--ink)] text-white" : "rounded-tl-md bg-white"}`}><p className="whitespace-pre-wrap">{message.body}</p><p className={`mt-2 text-[10px] ${message.isOwn ? "text-white/72" : "text-[color:var(--muted)]"}`}>{new Date(message.createdAt).toLocaleString("fr-FR")}</p></div></div>)}{!isLoading && data?.messages.length === 0 ? <div className="grid min-h-[420px] place-items-center"><div className="max-w-sm text-center"><Info className="mx-auto size-6 text-[color:var(--blue)]" /><p className="mt-4 font-semibold">La conversation est prête.</p><p className="mt-2 text-sm leading-6 text-[color:var(--muted)]">Écrivez votre première question. N’envoyez pas de document sensible ici : utilisez le centre documentaire privé.</p></div></div> : null}</div><div className="border-t border-[var(--line)] bg-white p-4"><div className="mb-3 flex items-center gap-2 text-xs text-[color:var(--muted)]"><ShieldCheck className="size-4" />Les pièces doivent être transmises depuis Documents.</div><div className="flex items-end gap-2 rounded-[20px] border border-[var(--line)] bg-[var(--paper)] p-2"><textarea rows={2} value={body} onChange={(event) => setBody(event.target.value)} placeholder="Rédiger un message…" className="max-h-36 flex-1 resize-none bg-transparent px-2 py-1 text-sm outline-none" /><button type="button" onClick={() => mutation.mutate()} disabled={!body.trim() || mutation.isPending || !data?.conversationId} className="grid size-11 shrink-0 place-items-center rounded-full bg-[var(--ink)] text-white disabled:opacity-35" aria-label="Envoyer"><ArrowUp className="size-4" /></button></div>{mutation.error ? <p className="mt-2 text-xs text-[color:var(--blue)]">{mutation.error instanceof Error ? mutation.error.message : "Envoi impossible"}</p> : null}</div></Card></div>;
}
